source_events.script_as3:
//执行移动
parent.$mc_ctrler.movePercent(-2,0); //参数为X,Y
parent.$mc_ctrler.dampingPercent(0.1,0); //移动阻尼，参数为X,Y

//执行移动
parent.$mc_ctrler.movePercent(2,0); //参数为X,Y
parent.$mc_ctrler.dampingPercent(0.3,0); //移动阻尼，参数为X,Y

//震动一次
parent.$effect_ctrler.shake(0,5);
//持续震动 parent.$effect_ctrler.startShake(0,3);
//结束震动 parent.$effect_ctrler.endShake();
parent.$effect_ctrler.shine();

parent.$mc_ctrler.setBishaSUPER();
parent.$mc_ctrler.setBishaUP();
parent.$mc_ctrler.setZhao3();
parent.$mc_ctrler.setDash();
//在结束时加上：parent.$mc_ctrler.endAct();

//执行移动
parent.$mc_ctrler.movePercent(3,0); //参数为X,Y
parent.$mc_ctrler.dampingPercent(0.1,0); //移动阻尼，参数为X,Y

//执行移动
parent.$mc_ctrler.movePercent(-2,0); //参数为X,Y
parent.$mc_ctrler.dampingPercent(0.1,0); //移动阻尼，参数为X,Y

//执行移动
parent.$mc_ctrler.movePercent(0,2); //参数为X,Y
parent.$mc_ctrler.setTouchFloor("空中必杀_TF",true); //参数为落地时的动作帧

//震动一次
parent.$effect_ctrler.shake(0,5);
//持续震动 parent.$effect_ctrler.startShake(0,3);
//结束震动 parent.$effect_ctrler.endShake();
//残影结束
parent.$effect_ctrler.endShadow();

//攻击区域检测[参数：检测MC名称，帧标签]
parent.$mc_ctrler.setHitTarget("cbs_chkm","超必杀_CHK");

parent.$mc_ctrler.setSteelBody(true,true);

//执行移动
parent.$mc_ctrler.movePercent(1.5,2); //参数为X,Y
parent.$mc_ctrler.setTouchFloor("跳招_TF",true); //参数为落地时的动作帧

//震动一次
parent.$effect_ctrler.shake(0,3);
//持续震动 parent.$effect_ctrler.startShake(0,3);
//结束震动 parent.$effect_ctrler.endShake();
//残影结束
parent.$effect_ctrler.endShadow();

//震动一次
parent.$effect_ctrler.shake(0,3);
//持续震动 parent.$effect_ctrler.startShake(0,3);
//结束震动 parent.$effect_ctrler.endShake();

//执行移动
parent.$mc_ctrler.movePercent(0,2); //参数为X,Y
parent.$mc_ctrler.setTouchFloor("空中必杀_TF",true); //参数为落地时的动作帧

//震动一次
parent.$effect_ctrler.shake(0,5);
//持续震动 parent.$effect_ctrler.startShake(0,3);
//结束震动 parent.$effect_ctrler.endShake();
//残影结束
parent.$effect_ctrler.endShadow();

//加入攻击对象[参数：MC名称，params]
/*
params 参数 {
	x:Number(速度X)|{moveToTarget:Boolean(是否移动到目标),followTarget:Boolean(是否跟随目标),offset:Number(距离目标偏移量),range:Array[left,right](攻击范围)} , 
	y:Number(速度Y)|{moveToTarget:Boolean(是否移动到目标),followTarget:Boolean(是否跟随目标),offset:Number(距离目标偏移量),range:Array[top,bottom](攻击范围)} , 
	applyG:Boolean(是否受重力影响) ,
}
*/
parent.$mc_ctrler.addAttacker("zh1mc");

//加入攻击对象[参数：MC名称，params]
/*
params 参数 {
	x:Number(速度X)|{moveToTarget:Boolean(是否移动到目标),followTarget:Boolean(是否跟随目标),offset:Number(距离目标偏移量),range:Array[left,right](攻击范围)} , 
	y:Number(速度Y)|{moveToTarget:Boolean(是否移动到目标),followTarget:Boolean(是否跟随目标),offset:Number(距离目标偏移量),range:Array[top,bottom](攻击范围)} , 
	applyG:Boolean(是否受重力影响) ,
}
*/
parent.$mc_ctrler.addAttacker("zh3mc",{applyG:false});

//执行移动
parent.$mc_ctrler.move(6,0); //参数为X,Y
parent.$mc_ctrler.damping(0.4,0); //移动阻尼，参数为X,Y

//加入攻击对象[参数：MC名称，params]
/*
params 参数 {
	x:Number(速度X)|{moveToTarget:Boolean(是否移动到目标),followTarget:Boolean(是否跟随目标),offset:Number(距离目标偏移量),range:Array[left,right](攻击范围)} , 
	y:Number(速度Y)|{moveToTarget:Boolean(是否移动到目标),followTarget:Boolean(是否跟随目标),offset:Number(距离目标偏移量),range:Array[top,bottom](攻击范围)} , 
	applyG:Boolean(是否受重力影响) ,
}
*/
parent.$mc_ctrler.addAttacker("bsmc",{applyG:false});

//发射[参数：MC名称，param]
/*
params 参数 {
	x:Number(速度X)|{moveToTarget:Boolean(是否移动到目标),followTarget:Boolean(是否跟随目标),offset:Number(距离目标偏移量)} , 
	y:Number(速度Y)|{moveToTarget:Boolean(是否移动到目标),followTarget:Boolean(是否跟随目标),offset:Number(距离目标偏移量)} , 
	applyG:Boolean(是否受重力影响) ,
}
*/
parent.$mc_ctrler.addAttacker("sbsmc",{x:{moveToTarget:true,offset:0,range:[50,300]},applyG:false});

//执行移动
parent.$mc_ctrler.move(-5,-10); //参数为X,Y
parent.$mc_ctrler.damping(0.3,0.3); //移动阻尼，参数为X,Y
